import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { sales, saleLineItems, payments, paymentAllocations, stockMovements, parts, vatRates, sequences, laborServices, bicycles, bicycleTemplates } from '@/db/schema.js'
import { eq, count as drizzleCount } from 'drizzle-orm'

// Type definitions for API responses
type SaleResponse = {
  sale: Record<string, unknown>
  payment: Record<string, unknown>
  lineItems: Record<string, unknown>[]
}

type SalesListResponse = {
  sales: Record<string, unknown>[]
  total: number
}

type SaleDetailResponse = {
  sale: Record<string, unknown>
  lineItems: Record<string, unknown>[]
  payments: Record<string, unknown>[]
  stockMovements: Record<string, unknown>[]
}

type VoidErrorResponse = {
  error: string
  code?: 'NOT_FOUND' | 'ALREADY_VOIDED' | 'INTERNAL_ERROR'
}

describe('Sales Routes — Integration Tests (consolidated sale.service.ts)', () => {
  // Helper to reset all relevant tables between tests
  async function resetTables() {
    await db.delete(stockMovements)
    await db.delete(paymentAllocations)
    await db.delete(payments)
    await db.delete(saleLineItems)
    await db.delete(sales)
    await db.delete(sequences)
    await db.delete(parts)
    await db.delete(vatRates)
  }

  beforeEach(async () => {
    await resetTables()
  })

  // ---------------------------------------------------------------------------
  // POST /api/sales — Create a direct sale (parts-only, existing behavior)
  // ---------------------------------------------------------------------------
  describe('POST /api/sales — parts-only sales', () => {
    it('should create a complete sale and return all entity types (tracer bullet)', async () => {
      // Seed data: VAT rate and parts with stock
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 },
        { id: 'p2', barcode: 'BAR-002', name: 'Chain Ring 50T', priceNet: 3000 }
      ])
      await db.insert(stockMovements).values([
        { id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' },
        { id: 'm2', partId: 'p2', quantityDelta: 5, reason: 'manual_correction' }
      ])

      // Create sale request (with lineType discriminator)
      const body = {
        paymentMethod: 'cash',
        lineItems: [
          { lineType: 'part', partId: 'p1', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' },
          { lineType: 'part', partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-standard', description: 'Chain Ring 50T' }
        ]
      }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)

      const json = await res.json() as SaleResponse
      expect(json.sale).toBeDefined()
      expect(json.payment).toBeDefined()
      expect(json.lineItems).toHaveLength(2)

      // Verify sale header has correct totals: 2×1000=2000 + 1×3000=3000 = 5000 net, VAT=1050, gross=6050
      expect((json.sale as Record<string, unknown>).subtotalNet).toBe(5000)
      expect((json.sale as Record<string, unknown>).vatTotal).toBe(1050)
      expect((json.sale as Record<string, unknown>).totalGross).toBe(6050)

      // Verify sale number format (SA-NNNN)
      expect((json.sale as Record<string, unknown>).saleNumber).toMatch(/^SA-\d{4}$/)

      // Verify payment amount matches gross total
      expect((json.payment as Record<string, unknown>).amount).toBe(6050)
      expect((json.payment as Record<string, unknown>).method).toBe('cash')

      // Verify line items have correct computed totals
      const lines = json.lineItems as Record<string, unknown>[]
      expect(lines[0].lineTotalNet).toBe(2000)
      expect(lines[0].lineTotalVat).toBe(420)
      expect(lines[0].lineTotalGross).toBe(2420)

      // Verify all 5 entity types have correct rows in DB
      const dbSales = await db.select().from(sales)
      const dbLines = await db.select().from(saleLineItems)
      const dbPayments = await db.select().from(payments)
      const dbAllocations = await db.select().from(paymentAllocations)
      const saleData = json.sale as Record<string, unknown>
      const dbMovements = await db.select().from(stockMovements).where(eq(stockMovements.referenceId, saleData.id as string))

      expect(dbSales).toHaveLength(1)
      expect(dbLines).toHaveLength(2)
      expect(dbPayments).toHaveLength(1)
      expect(dbAllocations).toHaveLength(1)
      expect(dbMovements).toHaveLength(2)

      // Verify stock movements have negative deltas (deduction)
      const part1Movement = dbMovements.find((m: { partId: string }) => m.partId === 'p1')
      const part2Movement = dbMovements.find((m: { partId: string }) => m.partId === 'p2')
      expect(part1Movement?.quantityDelta).toBe(-2)
      expect(part2Movement?.quantityDelta).toBe(-1)
    })

    it('should accept optional customerId for known customer sales', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 })
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      const body = {
        customerId: 'cust-abc-123',
        paymentMethod: 'card',
