  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, type TEXT NOT NULL DEFAULT 'private', first_name TEXT, last_name TEXT, company_name TEXT, vat_id TEXT, phone TEXT, email TEXT, street TEXT, number TEXT, bus TEXT, postal_code TEXT, city TEXT, country TEXT NOT NULL DEFAULT 'BE', notification_preference TEXT);`)
