import Database from 'better-sqlite3'
import { drizzle } from 'drizzle-orm/better-sqlite3'
import * as schema from './schema'
import * as fs from 'fs'
import * as path from 'path'

// Use in-memory DB for tests, file-based DB otherwise
const isTest = process.env.NODE_ENV === 'test' || process.env.VITEST === 'true'
const DB_PATH = isTest ? ':memory:' : path.join(process.cwd(), '..', 'data', 'database.db')

let sqliteDb: Database.Database

if (isTest) {
  // In-memory database for tests — completely isolated, no disk writes
  sqliteDb = new Database(':memory:')
} else {
  // Ensure data directory exists
  const dataDir = path.dirname(DB_PATH)
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true })
  }
  // Open database synchronously (much faster than sql.js)
  sqliteDb = new Database(DB_PATH)
}

// Enable WAL mode for better performance with concurrent reads/writes
sqliteDb.pragma('journal_mode = WAL')

/**
 * Initialize all tables from the Drizzle schema.
 *
 * Uses explicit CREATE TABLE statements that mirror the schema.ts definitions.
 * This ensures test and production databases stay in sync.
 */
export function initializeTables() {
  // Each statement must be terminated with a semicolon for exec() to parse correctly
  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, type TEXT NOT NULL DEFAULT 'private', first_name TEXT, last_name TEXT, company_name TEXT, vat_id TEXT, phone TEXT, email TEXT, street TEXT, number TEXT, bus TEXT, postal_code TEXT, city TEXT, country TEXT NOT NULL DEFAULT 'BE', notification_preference TEXT);`)

  // Migrate: backfill address columns if they don't exist (schema was updated from single 'address' column)
  try { sqliteDb.exec(`ALTER TABLE customers ADD COLUMN street TEXT`) } catch {}
  try { sqliteDb.exec(`ALTER TABLE customers ADD COLUMN number TEXT`) } catch {}
  try { sqliteDb.exec(`ALTER TABLE customers ADD COLUMN bus TEXT`) } catch {}
  try { sqliteDb.exec(`ALTER TABLE customers ADD COLUMN postal_code TEXT`) } catch {}
  try { sqliteDb.exec(`ALTER TABLE customers ADD COLUMN city TEXT`) } catch {}
  try { sqliteDb.exec(`ALTER TABLE customers ADD COLUMN country TEXT NOT NULL DEFAULT 'BE'`) } catch {}

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'mechanic', hourly_rate INTEGER NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS vat_rates (id TEXT PRIMARY KEY, rate INTEGER NOT NULL UNIQUE, description TEXT NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS parts (id TEXT PRIMARY KEY, barcode TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, price_net INTEGER NOT NULL, cost_price INTEGER, quantity_on_hand INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS labor_services (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, billing_type TEXT NOT NULL, default_rate INTEGER NOT NULL, is_active INTEGER NOT NULL DEFAULT 1);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS bicycle_templates (id TEXT PRIMARY KEY, brand TEXT NOT NULL, model TEXT NOT NULL, description TEXT, base_price_net INTEGER, is_active INTEGER NOT NULL DEFAULT 1);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS bicycles (id TEXT PRIMARY KEY, source TEXT NOT NULL DEFAULT 'customer_owned', template_id TEXT, customer_id TEXT, brand TEXT NOT NULL, model TEXT NOT NULL, year INTEGER, color TEXT, frame_size TEXT, status TEXT NOT NULL DEFAULT 'inventory', created_at INTEGER NOT NULL);`)

  // Migrate: add is_lease column to bicycles if it doesn't exist
  try { sqliteDb.exec(`ALTER TABLE bicycles ADD COLUMN is_lease INTEGER NOT NULL DEFAULT 0`) } catch {}

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS quotes (id TEXT PRIMARY KEY, quote_number TEXT NOT NULL UNIQUE, customer_id TEXT, status TEXT NOT NULL DEFAULT 'draft', notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS quote_line_items (id TEXT PRIMARY KEY, quote_id TEXT NOT NULL, line_type TEXT NOT NULL, part_id TEXT, labor_service_id TEXT, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price_net INTEGER NOT NULL, vat_rate_id TEXT NOT NULL, discount_percent INTEGER, line_total_net INTEGER NOT NULL, line_total_vat INTEGER NOT NULL, line_total_gross INTEGER NOT NULL, bicycle_id TEXT, bicycle_brand TEXT, bicycle_model TEXT, bicycle_year INTEGER, bicycle_color TEXT, bicycle_frame_size TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS repairs (id TEXT PRIMARY KEY, bicycle_id TEXT NOT NULL, assigned_to TEXT, status TEXT NOT NULL DEFAULT 'intake', customer_notes TEXT, internal_notes TEXT, hold_reason TEXT, hold_reason_note TEXT, planned_date INTEGER, pickup_date INTEGER, completed_at INTEGER, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS repair_line_items (id TEXT PRIMARY KEY, repair_id TEXT NOT NULL, line_type TEXT NOT NULL, part_id TEXT, labor_service_id TEXT, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price_net INTEGER NOT NULL, vat_rate_id TEXT NOT NULL, discount_percent INTEGER, line_total_net INTEGER NOT NULL, line_total_vat INTEGER NOT NULL, line_total_gross INTEGER NOT NULL, bicycle_id TEXT, bicycle_brand TEXT, bicycle_model TEXT, bicycle_year INTEGER, bicycle_color TEXT, bicycle_frame_size TEXT, minutes_worked INTEGER, hourly_rate_snapshot INTEGER, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS work_logs (id TEXT PRIMARY KEY, repair_id TEXT NOT NULL, user_id TEXT NOT NULL, started_at INTEGER NOT NULL, ended_at INTEGER);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS repair_status_history (id TEXT PRIMARY KEY, repair_id TEXT NOT NULL, status TEXT NOT NULL, transitioned_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS customer_orders (id TEXT PRIMARY KEY, order_number TEXT NOT NULL UNIQUE, customer_id TEXT, status TEXT NOT NULL DEFAULT 'pending', total_price_net INTEGER NOT NULL, expected_delivery_date INTEGER, internal_notes TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS customer_order_line_items (id TEXT PRIMARY KEY, customer_order_id TEXT NOT NULL, line_type TEXT NOT NULL, part_id TEXT, labor_service_id TEXT, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price_net INTEGER NOT NULL, vat_rate_id TEXT NOT NULL, discount_percent INTEGER, line_total_net INTEGER NOT NULL, line_total_vat INTEGER NOT NULL, line_total_gross INTEGER NOT NULL, bicycle_id TEXT, bicycle_brand TEXT, bicycle_model TEXT, bicycle_year INTEGER, bicycle_color TEXT, bicycle_frame_size TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS customer_order_status_history (id TEXT PRIMARY KEY, customer_order_id TEXT NOT NULL, status TEXT NOT NULL, transitioned_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS backorders (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, total_price_net INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'requested', expected_delivery_date INTEGER, internal_notes TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS backorder_line_items (id TEXT PRIMARY KEY, backorder_id TEXT NOT NULL, line_type TEXT NOT NULL, part_id TEXT, labor_service_id TEXT, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price_net INTEGER NOT NULL, vat_rate_id TEXT NOT NULL, discount_percent INTEGER, line_total_net INTEGER NOT NULL, line_total_vat INTEGER NOT NULL, line_total_gross INTEGER NOT NULL, bicycle_id TEXT, bicycle_brand TEXT, bicycle_model TEXT, bicycle_year INTEGER, bicycle_color TEXT, bicycle_frame_size TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS backorder_status_history (id TEXT PRIMARY KEY, backorder_id TEXT NOT NULL, status TEXT NOT NULL, transitioned_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS sales (id TEXT PRIMARY KEY, sale_number TEXT NOT NULL UNIQUE, customer_id TEXT, source_type TEXT NOT NULL, source_id TEXT, status TEXT NOT NULL DEFAULT 'completed', subtotal_net INTEGER NOT NULL, vat_total INTEGER NOT NULL, total_gross INTEGER NOT NULL, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS sale_line_items (id TEXT PRIMARY KEY, sale_id TEXT NOT NULL, line_type TEXT NOT NULL, part_id TEXT, labor_service_id TEXT, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price_net INTEGER NOT NULL, vat_rate_id TEXT NOT NULL, discount_percent INTEGER, line_total_net INTEGER NOT NULL, line_total_vat INTEGER NOT NULL, line_total_gross INTEGER NOT NULL, bicycle_id TEXT, bicycle_brand TEXT, bicycle_model TEXT, bicycle_year INTEGER, bicycle_color TEXT, bicycle_frame_size TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, invoice_number TEXT NOT NULL UNIQUE, sale_id TEXT NOT NULL UNIQUE, customer_id TEXT, status TEXT NOT NULL DEFAULT 'issued', subtotal_net INTEGER NOT NULL, vat_total INTEGER NOT NULL, total_gross INTEGER NOT NULL, issued_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS invoice_line_items (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL, line_type TEXT NOT NULL, part_id TEXT, labor_service_id TEXT, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price_net INTEGER NOT NULL, vat_rate_id TEXT NOT NULL, discount_percent INTEGER, line_total_net INTEGER NOT NULL, line_total_vat INTEGER NOT NULL, line_total_gross INTEGER NOT NULL, bicycle_id TEXT, bicycle_brand TEXT, bicycle_model TEXT, bicycle_year INTEGER, bicycle_color TEXT, bicycle_frame_size TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, method TEXT NOT NULL, amount INTEGER NOT NULL, reference_number TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS payment_allocations (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, allocated_amount INTEGER NOT NULL);`)

  // Composite unique: same EAN can appear with different suppliers
  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS supplier_products (id TEXT PRIMARY KEY, ean_upc TEXT NOT NULL, raw_json TEXT NOT NULL, supplier_name TEXT NOT NULL, searched_at INTEGER NOT NULL, UNIQUE(ean_upc, supplier_name));`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS supplier_orders (id TEXT PRIMARY KEY, supplier_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reference_number TEXT, ordered_at INTEGER, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS supplier_order_lines (id TEXT PRIMARY KEY, order_id TEXT NOT NULL, ean_upc TEXT NOT NULL, part_id TEXT, quantity_ordered INTEGER NOT NULL DEFAULT 1, quantity_received INTEGER NOT NULL DEFAULT 0);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS stock_movements (id TEXT PRIMARY KEY, part_id TEXT NOT NULL, quantity_delta INTEGER NOT NULL, reason TEXT NOT NULL, reference_type TEXT, reference_id TEXT, created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS gransier_products (id TEXT PRIMARY KEY, ean_upc TEXT NOT NULL UNIQUE, item_number TEXT, brand TEXT, name TEXT NOT NULL, description TEXT, cost_price_net INTEGER, sell_price_net INTEGER NOT NULL, vat_rate_basis_points INTEGER NOT NULL DEFAULT 2100, image_url TEXT, category TEXT, color TEXT, is_active INTEGER NOT NULL DEFAULT 1);`)

  sqliteDb.exec(`CREATE INDEX IF NOT EXISTS gransier_products_ean_idx ON gransier_products(ean_upc);`)
  sqliteDb.exec(`CREATE INDEX IF NOT EXISTS gransier_products_name_brand_idx ON gransier_products(name, brand);`)

  // Kruitbosch product catalog — denormalized columns (replaces raw_json supplier_products)
  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS kruitbosch_products (id TEXT PRIMARY KEY, ean_upc TEXT NOT NULL UNIQUE, item_number TEXT, brand TEXT, model TEXT, name TEXT NOT NULL, description TEXT, cost_price_net INTEGER, sell_price_net INTEGER NOT NULL, vat_rate_basis_points INTEGER NOT NULL DEFAULT 2100, image_url TEXT, category TEXT, color TEXT, is_active INTEGER NOT NULL DEFAULT 1);`)
  sqliteDb.exec(`CREATE INDEX IF NOT EXISTS kruitbosch_products_ean_idx ON kruitbosch_products(ean_upc);`)
  sqliteDb.exec(`CREATE INDEX IF NOT EXISTS kruitbosch_products_name_brand_idx ON kruitbosch_products(name, brand);`)

  // ── Belgian Address Data (BOSA BEVLG) ───────────────────────

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS postal_codes (
    code TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    region_code TEXT NOT NULL
  );`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS address_streets (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    municipality TEXT NOT NULL,
    postal_code TEXT NOT NULL,
    region_code TEXT NOT NULL
  );`)

  // Indexes for fast autocomplete queries (no-op if index already exists)
  sqliteDb.exec(`CREATE INDEX IF NOT EXISTS idx_address_streets_postal_code ON address_streets(postal_code);`)
  sqliteDb.exec(`CREATE INDEX IF NOT EXISTS idx_address_streets_name_postal ON address_streets(name, postal_code);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS address_sync_metadata (
    region_key TEXT PRIMARY KEY,
    last_synced_at INTEGER NOT NULL,
    record_count_postal_codes INTEGER NOT NULL DEFAULT 0,
    record_count_streets INTEGER NOT NULL DEFAULT 0
  );`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, customer_id TEXT, source_type TEXT, source_id TEXT, channel TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL);`)

  sqliteDb.exec(`CREATE TABLE IF NOT EXISTS sequences (name TEXT PRIMARY KEY, current_value INTEGER NOT NULL DEFAULT 0);`)

  // Seed initial sequence values — only inserts if row doesn't exist (no-op on existing DBs)
  sqliteDb.exec("INSERT OR IGNORE INTO sequences (name, current_value) VALUES ('sale', 0)")
}

// Initialize tables on module load so any import gets a ready-to-use DB
initializeTables()

/**
 * Export the raw better-sqlite3 database for direct access when needed.
 */
export { sqliteDb }

/**
 * Create Drizzle ORM instance
 */
export const db = drizzle(sqliteDb, { schema })

